    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            candidates = [grid[h - 1 - r][c], grid[r][w - 1 - c], grid[h - 1 - r][w - 1 - c]]
            values = [value for value in candidates if value != 2]
            if values:
                out[r][c] = values[0]
    return out
'''
